<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:DejaVu Sans,sans-serif;font-size:10px;color:#17212b}h1{text-align:center;color:#1f7a5b}.meta{text-align:center;color:#667085;margin-bottom:16px}table{border-collapse:collapse;width:100%}th,td{border:1px solid #aab4bd;padding:6px;text-align:left}th{background:#1f7a5b;color:#fff}.number{text-align:right}</style></head><body><h1>{{ $title }}</h1>@if($meta)<div class="meta">@foreach($meta as $key=>$value)<span><strong>{{ $key }}:</strong> {{ $value }} &nbsp;</span>@endforeach</div>@endif<table><thead><tr>@foreach($headers as $header)<th>{{ $header }}</th>@endforeach</tr></thead><tbody>@foreach($rows as $row)<tr>@foreach($row as $value)<td>{{ (is_int($value) || is_float($value)) ? number_format((float)$value, 2) : $value }}</td>@endforeach</tr>@endforeach</tbody></table></body></html>
